<script lang="ts">
 import{onDestroy}from'svelte';import{Api}from'./lib/api';import type{Snapshot,DirectMessage,Message,SearchPage}from'./lib/api';import MessageText from'./MessageText.svelte';
 export let api:Api;export let snapshot:Snapshot;export let dms:DirectMessage[];export let onJump:(message:Message)=>void;export let onLink:(url:string)=>void;
 let query='',author='',channel='',from='',to='',results:Message[]=[],cursor:string|null=null,loading=false,error='',searched=false,appliedParams='';let abort:AbortController|undefined;let version=0;
 const where=(id:string)=>{const dm=dms.find(d=>d.id===id);return dm?'DM with '+dm.user.display_name:'#'+(snapshot.channels.find(c=>c.id===id)?.name??'channel');};
 async function search(more=false){if(loading)return;if(!more&&!query.trim()&&!author&&!channel&&!from&&!to){error='Enter search text or choose at least one filter.';return;}abort?.abort();abort=new AbortController();const current=++version;loading=true;error='';let params=new URLSearchParams({limit:'25'});if(query.trim())params.set('q',query.trim());if(author)params.set('author_id',author);if(channel)params.set('channel_id',channel);if(from)params.set('from',new Date(from+'T00:00:00').toISOString());if(to)params.set('to',new Date(to+'T23:59:59.999').toISOString());if(more&&appliedParams)params=new URLSearchParams(appliedParams);const candidateParams=params.toString();if(more&&cursor)params.set('before',cursor);try{const page=await api.request<SearchPage>('/search?'+params,'GET',undefined,abort.signal);if(current===version){if(!more)appliedParams=candidateParams;results=more?[...results,...page.results.filter(m=>!results.some(old=>old.id===m.id))]:page.results;cursor=page.next_before;searched=true;}}catch(cause){if(current===version&&!abort.signal.aborted)error=cause instanceof Error?cause.message:'Search failed.';}finally{if(current===version)loading=false;}}
 onDestroy(()=>{version++;abort?.abort();});
</script>
<h2 id="dialog-title">Search messages</h2><p class="small muted">Search channels you can access and your direct messages in this community. All words must match; use quotes for a phrase.</p>
<form onsubmit={event=>{event.preventDefault();void search();}}><label>Search text<input type="search" bind:value={query} maxlength="1000" placeholder="Words or &quot;exact phrase&quot;"/></label><div class="search-filters"><label>Channel or conversation<select bind:value={channel}><option value="">All conversations</option>{#each snapshot.channels.filter(c=>c.type==='text') as c}<option value={c.id}>#{c.name}</option>{/each}{#each dms as dm}<option value={dm.id}>DM with {dm.user.display_name}</option>{/each}</select></label><label>Author<select bind:value={author}><option value="">Anyone</option>{#each snapshot.members as m}<option value={m.user.id}>{m.user.display_name} (@{m.user.username})</option>{/each}</select></label><label>From date<input type="date" bind:value={from}/></label><label>Through date<input type="date" bind:value={to}/></label></div><button class="primary" disabled={loading}>{loading?'Searching…':'Search'}</button></form>
{#if error}<p class="error" role="alert">{error}</p>{/if}{#if searched&&!results.length}<p class="notice">No matching messages.</p>{/if}
<div class="search-results">{#each results as result(result.id)}<article class="search-result"><p class="small muted">{where(result.channel_id)} · {result.author.display_name} · {new Date(result.created_at).toLocaleString()}</p><p class="search-content"><MessageText content={result.content||'(Attachment)'} members={snapshot.members} roles={snapshot.roles} channels={snapshot.channels} selfId={snapshot.user.id} {onLink}/></p><button class="secondary" onclick={()=>onJump(result)}>Jump to message</button></article>{/each}</div>
{#if cursor}<button class="secondary" disabled={loading} onclick={()=>search(true)}>Load more results</button>{/if}
<style>.search-filters{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 16px}.search-result{padding:14px 0;border-top:1px solid #3a4a53}.search-content{white-space:pre-wrap;overflow-wrap:anywhere;max-height:220px;overflow:auto}.search-result .small{margin:0 0 10px}@media(max-width:500px){.search-filters{grid-template-columns:1fr}}</style>
